import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  sidebarOpen: true,
  mobileMenuOpen: false,
  theme: 'light',
  language: 'en',
  notifications: [],
  modals: {
    profile: false,
    settings: false,
    fileUpload: false,
    imagePreview: false,
  },
  loading: {
    global: false,
    auth: false,
    chat: false,
    upload: false,
  },
  toast: {
    show: false,
    message: '',
    type: 'info', // info, success, error, warning
  },
  chatView: 'list', // list, chat, search
  searchQuery: '',
  selectedUsers: [],
  isTyping: false,
  typingTimeout: null,
};

const uiSlice = createSlice({
  name: 'ui',
  initialState,
  reducers: {
    toggleSidebar: (state) => {
      state.sidebarOpen = !state.sidebarOpen;
    },
    setSidebarOpen: (state, action) => {
      state.sidebarOpen = action.payload;
    },
    toggleMobileMenu: (state) => {
      state.mobileMenuOpen = !state.mobileMenuOpen;
    },
    setMobileMenuOpen: (state, action) => {
      state.mobileMenuOpen = action.payload;
    },
    setTheme: (state, action) => {
      state.theme = action.payload;
      localStorage.setItem('theme', action.payload);
    },
    setLanguage: (state, action) => {
      state.language = action.payload;
      localStorage.setItem('language', action.payload);
    },
    addNotification: (state, action) => {
      state.notifications.push({
        id: Date.now(),
        ...action.payload,
        timestamp: new Date().toISOString(),
      });
    },
    removeNotification: (state, action) => {
      state.notifications = state.notifications.filter(
        notification => notification.id !== action.payload
      );
    },
    clearNotifications: (state) => {
      state.notifications = [];
    },
    openModal: (state, action) => {
      state.modals[action.payload] = true;
    },
    closeModal: (state, action) => {
      state.modals[action.payload] = false;
    },
    closeAllModals: (state) => {
      Object.keys(state.modals).forEach(modal => {
        state.modals[modal] = false;
      });
    },
    setLoading: (state, action) => {
      const { type, loading } = action.payload;
      state.loading[type] = loading;
    },
    showToast: (state, action) => {
      state.toast = {
        show: true,
        message: action.payload.message,
        type: action.payload.type || 'info',
      };
    },
    hideToast: (state) => {
      state.toast.show = false;
    },
    setChatView: (state, action) => {
      state.chatView = action.payload;
    },
    setSearchQuery: (state, action) => {
      state.searchQuery = action.payload;
    },
    setSelectedUsers: (state, action) => {
      state.selectedUsers = action.payload;
    },
    addSelectedUser: (state, action) => {
      if (!state.selectedUsers.includes(action.payload)) {
        state.selectedUsers.push(action.payload);
      }
    },
    removeSelectedUser: (state, action) => {
      state.selectedUsers = state.selectedUsers.filter(
        userId => userId !== action.payload
      );
    },
    clearSelectedUsers: (state) => {
      state.selectedUsers = [];
    },
    setIsTyping: (state, action) => {
      state.isTyping = action.payload;
    },
    setTypingTimeout: (state, action) => {
      state.typingTimeout = action.payload;
    },
    resetUI: (state) => {
      return {
        ...initialState,
        theme: state.theme,
        language: state.language,
      };
    },
  },
});

export const {
  toggleSidebar,
  setSidebarOpen,
  toggleMobileMenu,
  setMobileMenuOpen,
  setTheme,
  setLanguage,
  addNotification,
  removeNotification,
  clearNotifications,
  openModal,
  closeModal,
  closeAllModals,
  setLoading,
  showToast,
  hideToast,
  setChatView,
  setSearchQuery,
  setSelectedUsers,
  addSelectedUser,
  removeSelectedUser,
  clearSelectedUsers,
  setIsTyping,
  setTypingTimeout,
  resetUI,
} = uiSlice.actions;

export default uiSlice.reducer;
